import { test, expect } from '@playwright/test';

test.describe('File Upload Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload'); // Replace with the actual URL of the upload page
  });

  test('should allow user to upload multiple files', async ({ page }) => {
    const fileInput = page.getByLabel('Upload Files'); // Replace with the actual label of the file input
    await fileInput.setInputFiles(['file1.txt', 'file2.txt', 'file3.txt']); // Replace with actual file paths

    const uploadButton = page.getByRole('button', { name: 'Upload' }); // Replace with the actual button name
    await uploadButton.click();

    const successMessage = page.getByText('Files uploaded successfully'); // Replace with the actual success message
    await expect(successMessage).toBeVisible();
  });

  test('should show error for unsupported file types', async ({ page }) => {
    const fileInput = page.getByLabel('Upload Files'); // Replace with the actual label of the file input
    await fileInput.setInputFiles(['unsupported_file.exe']); // Replace with an unsupported file type

    const uploadButton = page.getByRole('button', { name: 'Upload' }); // Replace with the actual button name
    await uploadButton.click();

    const errorMessage = page.getByText('Unsupported file type'); // Replace with the actual error message
    await expect(errorMessage).toBeVisible();
  });
});
